import "./ViewSRFItem.css";
import { Modal, Button, FileSelector } from "react-rainbow-components";
import StatusBadge from "../../UI/StatusBadge";
import CustomProgress from "../../UI/CustomProgress";
import config from "../../../utils/config.json";
import { useContext, useState } from "react";
import { AuthContext } from "../../../context/auth-context";

const containerStyles = {
  maxWidth: 300,
};

const ViewSRFItem = (props) => {
  //console.log(props.item);

  return (
    <>
      <Modal
        id="modal-1"
        isOpen={props.isOpen}
        onRequestClose={props.onclose}
        className="view__srf__item__modal"
      >
        <h2 className="srf_item_detail center">SRF Item Detail</h2>

        <div className="srf__item__details__container">
          <div className="srf__item__detail">
            <p className="bold">
              SNo: <span className="red">{props.item.sno}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Description: <span className="red">{props.item.description}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Make: <span className="red">{props.item.make}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Model: <span className="red">{props.item.model}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Range Minimum: <span className="red">{props.item.range_min}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Range Maximum: <span className="red">{props.item.range_max}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Range Unit: <span className="red">{props.item.range_unit}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Serial No: <span className="red">{props.item.serialno}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Id No: <span className="red">{props.item.idno}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Status: <StatusBadge value={props.item.status} />
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              SRF No: <span className="red">{props.item.srfNo}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Calibration Done Date:{" "}
              <span className="red">
                {props.item.calibration_done_date
                  ?.split("-")
                  .reverse()
                  .join("-")}
              </span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Calibration Done Name:{" "}
              <span className="red">{props.item.calibration_done_name}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Report Done Date:{" "}
              <span className="red">
                {props.item.report_done_date?.split("-").reverse().join("-")}
              </span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Report Done Name:{" "}
              <span className="red">{props.item.report_done_name}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Report Dispatch Date:{" "}
              <span className="red">{props.item.report_dispatch_date}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Report Dispatch Mode:{" "}
              <span className="red">{props.item.report_dispatch_mode}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Item Dispatch Date:{" "}
              <span className="red">
                {props.item.dispatch_date?.split("-").reverse().join("-")}
              </span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Item Dispatch DC:{" "}
              <span className="red">{props.item.dispatch_dc}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Item Dispatch Mode:{" "}
              <span className="red">{props.item.dispatch_mode}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              ULR No: <span className="red">{props.item.ulrno}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Invoice No: <span className="red">{props.item.invoice_no}</span>
            </p>
          </div>
          <div className="srf__item__detail">
            <p className="bold">
              Remarks: <span className="red">{props.item.remarks}</span>
            </p>
          </div>
          <CustomProgress
            options={config.SRF_ITEM_STATUS_LIST}
            current={props.item.status}
          />
        </div>
      </Modal>
    </>
  );
};

export default ViewSRFItem;
