import "./ItemsFilter.css";
import { Card } from "react-rainbow-components";
import CustomSearch from "../../Inputs/CustomSearch";
import { useDispatch, useSelector } from "react-redux";
import { useContext, useEffect, useState } from "react";
import FilteredItems from "./FilteredItems";
import { AuthContext } from "../../../context/auth-context";
import config from "../../../utils/config.json";
import { filtereditemsActions } from "../../../store/filtereditems";

const ItemsFilter = () => {
  const allitems = useSelector((state) => state.filtereditems.list);
  const [filtereditems, setFilteredItems] = useState([]);
  const auth = useContext(AuthContext);
  const [isLoaded, setIsLoaded] = useState(true);
  const filteredSRFs = useSelector((state) => state.filteredsrfs.list);
  const dispatch = useDispatch();
  useEffect(() => {
    if (filteredSRFs.length > 0) {
      const srfids = [];
      //console.log(filteredSRFs);
      filteredSRFs.forEach((element) => {
        srfids.push(element.id);
      });
      //console.log(srfids);
      const requestOptions = {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + auth.token,
        },
        body: JSON.stringify({ labId: auth.labId, srfIds: srfids }),
      };

      fetch(config.SERVER.URL + "/api/srf/getfilteredsrfitems", requestOptions)
        .then(async (response) => {
          const data = await response.json();

          if (data) {
            if (data.code === 200) {
              //console.log(data.data);
              setIsLoaded(true);
              data.data.items.forEach((element) => {
                filteredSRFs.forEach((fs) => {
                  if (element.srfId.toString() == fs.id) {
                    element.srfNo = fs.srfId;
                  }
                });
              });
              dispatch(filtereditemsActions.changeitems(data.data.items));
              //dispatch(srfsActions.changesrfs(data.data));
            } else {
              setIsLoaded(true);
            }
          } else {
            setIsLoaded(true);
          }
        })
        .catch((err) => {
          setIsLoaded(true);
        });
    }
  }, [filteredSRFs]);
  return (
    <>
      <div className="items__filter">
        <Card className="srfs__card">
          <div className="srfs__label">
            <h3>SRF Items Filter</h3>
          </div>
          <div className="searchers__container">
            <div className="searchers">
              <CustomSearch
                options={allitems}
                onfilter={(v) => setFilteredItems(v)}
                filterby="serialno"
                label="Search By Serial No."
              />
            </div>
            <div className="searchers">
              <CustomSearch
                options={allitems}
                onfilter={(v) => setFilteredItems(v)}
                filterby="dispatch_dc"
                label="Search By Dispatch DC"
              />
            </div>
            <div className="searchers">
              <CustomSearch
                options={allitems}
                onfilter={(v) => setFilteredItems(v)}
                filterby="idno"
                label="Search By Id No"
              />
            </div>
          </div>
        </Card>
      </div>
      <FilteredItems items={filtereditems} />
    </>
  );
};

export default ItemsFilter;
