import "./SideBar.css";
import { Sidebar, SidebarItem } from "react-rainbow-components";
import {
  FcBusinessman,
  FcFactory,
  FcImport,
  FcList,
  FcPortraitMode,
  FcWorkflow,
  FcInvite,
  FcSurvey,
} from "react-icons/fc";
import { useDispatch, useSelector } from "react-redux";
import { sidebarActions } from "../../store/sidebar";
import { useContext } from "react";
import { AuthContext } from "../../context/auth-context";
const iconsize = 30;

const SideBar = (props) => {
  const dispatch = useDispatch();
  const auth = useContext(AuthContext);
  const sidebar = useSelector((state) => state.sidebar.current);
  const sidebarHandler = (e, v) => {
    dispatch(sidebarActions.changesidebar(v));
    //console.log(v);
  };
  return (
    <div className="sidebar__container rainbow-p-top_small rainbow-p-bottom_medium">
      <Sidebar selectedItem={sidebar} onSelect={sidebarHandler} id="sidebar-1">
        {auth.department !== "root" ? (
          <SidebarItem
            icon={<FcWorkflow size={iconsize} />}
            name="SRFs"
            label="SRFs"
          />
        ) : null}

        {/*auth.department === "Accounts" || auth.department === "admin" ? (
          <SidebarItem
            icon={<FcSurvey size={iconsize} />}
            name="Invoices"
            label="Invoices"
          />
        ) : null*/}
        {auth.department === "admin" ? (
          <SidebarItem
            icon={<FcPortraitMode size={iconsize} />}
            name="Users"
            label="Users"
          />
        ) : null}
        {auth.department === "CSD" || auth.department === "admin" ? (
          <SidebarItem
            icon={<FcImport size={iconsize} />}
            name="Add SRF"
            label="Add SRF"
          />
        ) : null}
        {auth.department === "admin" ? (
          <SidebarItem
            icon={<FcBusinessman size={iconsize} />}
            name="Add User"
            label="Add User"
          />
        ) : null}

        {auth.department === "admin" ? (
          <SidebarItem
            icon={<FcList size={iconsize} />}
            name="MasterList"
            label="MasterList"
          />
        ) : null}
        {/*Later will be changed to root*/}
        {auth.department === "root" ? (
          <SidebarItem
            icon={<FcFactory size={iconsize} />}
            name="Labs"
            label="Labs"
          />
        ) : null}
        {auth.department === "admin" ? (
          <SidebarItem
            icon={<FcInvite size={iconsize} />}
            name="E-Mail"
            label="E-Mail"
          />
        ) : null}
      </Sidebar>
    </div>
  );
};

export default SideBar;
