import "./AddItem.css";
import { Spinner, Button, Modal } from "react-rainbow-components";
import CustomInput from "../../Inputs/CustomInput";
import CustomTextArea from "../../Inputs/CustomTextArea";
import { useContext, useEffect, useState } from "react";
import { itemSchema } from "../../../Schemas/item";
import { useDispatch, useSelector } from "react-redux";
import { itemsActions } from "../../../store/items";
import { notificationActions } from "../../../store/nofitication";
import CustomSelect from "../../Inputs/CustomSelect";
import { masterlistActions } from "../../../store/masterlist";
import { AuthContext } from "../../../context/auth-context";
import config from "../../../utils/config.json";
import CustomLookup1 from "../../Inputs/CustomLookup1";

const AddItem = (props) => {
  const [isLoaded, setisLoaded] = useState(true);
  const [error, setError] = useState("");
  const [description, setDescription] = useState("");
  const [make, setMake] = useState("");
  const [model, setModel] = useState("");
  const [rangemin, setRangeMin] = useState();
  const [rangemax, setRangeMax] = useState();
  const [rangeunit, setRangeUnit] = useState("mm");
  const [serialno, setSerialNo] = useState("");
  const [idno, setIdno] = useState("");
  const [remarks, setRemarks] = useState("");
  const [ulrno, setULRNo] = useState();
  const [masterlistId, setmasterListId] = useState();
  const dispatch = useDispatch();
  const masterlist = useSelector((state) => state.masterlist.list);
  const auth = useContext(AuthContext);
  const [unitOptions, setUnitOptions] = useState([]);
  useEffect(() => {
    const requestOptions = {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + auth.token,
      },
      body: JSON.stringify({ labId: auth.labId }),
    };
    const errornotification = {
      title: "Error while getting MasterList!!",
      description: "Getting masterlist from server failed!!",
      icon: "error",
      state: true,
      timeout: 15000,
    };
    fetch(config.SERVER.URL + "/api/masterlist/getall", requestOptions)
      .then(async (response) => {
        const data = await response.json();
        setisLoaded(true);
        ////console.log(data);
        if (data) {
          if (data.code === 200) {
            ////console.log(data);
            let oldmasterlist = data.data;
            const modified = oldmasterlist.map((v, i) => {
              return { id: v.id, sno: i + 1, name: v.name, units: v.units };
            });
            dispatch(masterlistActions.changeitems(modified));
          } else {
            setError(data.message);
            const newNotification = {
              title: "Getting Masterlist Failed!!",
              description: data.message,
              icon: "error",
              state: true,
            };
            dispatch(notificationActions.changenotification(newNotification));
          }
        } else {
          setError("Error While Getting Masterlist!!");
        }
      })
      .catch((err) => {
        setisLoaded(true);
        setError("Error While Getting Masterlist!!");
      });
  }, []);
  const newitemHandler = async () => {
    setisLoaded(false);
    const newitem = {
      description,
      make,
      model,
      range_min: rangemin,
      range_max: rangemax,
      range_unit: rangeunit,
      serialno,
      idno,
      remarks,
      ulrno,
      masterlistId: masterlistId,
    };
    //console.log(newitem);
    const isValid = await itemSchema.isValid(newitem);
    if (!isValid) {
      setError("Input Validation Failed!! Please Check!!");
      setisLoaded(true);
      return;
    }
    const newNotification = {
      title: "Item Added Successfully",
      description: description,
      icon: "info",
      state: true,
      timeout: 10000,
    };
    dispatch(itemsActions.additem(newitem));
    dispatch(notificationActions.changenotification(newNotification));
    props.onclose();
  };
  const selectItemHandler = (v) => {
    setDescription(v.name);
    setmasterListId(v.id);
    console.log(v);
    let unitoptions = v.units.map((v, i) => {
      return { label: v, value: v };
    });
    setUnitOptions(unitoptions);
  };
  return (
    <div className="new__item__modal__container">
      <Modal
        id="modal-2"
        isOpen={props.isopen}
        onRequestClose={props.onclose}
        title="New Item"
        footer={
          <div className="rainbow-flex center">
            <p className="red">{error}</p>
            {!isLoaded ? <Spinner size="medium" /> : null}
            <Button label="Add Item" variant="brand" onClick={newitemHandler} />
          </div>
        }
      >
        <div className="new__item__modal__body">
          <div className="new__item__item">
            <CustomLookup1
              options={masterlist}
              onselect={(v) => selectItemHandler(v)}
              label={"Description of Item"}
              required={true}
            />
          </div>
          <div className="new__item__item">
            <CustomInput
              label="Make"
              value={make}
              type="text"
              required={true}
              onchange={(v) => setMake(v)}
            />
          </div>
          <div className="new__item__item">
            <CustomInput
              label="Model"
              value={model}
              type="text"
              required={true}
              onchange={(v) => setModel(v)}
            />
          </div>
          <div className="new__item__item">
            <CustomInput
              label="Range Min."
              value={rangemin}
              type="number"
              required={true}
              onchange={(v) => setRangeMin(parseInt(v))}
            />
          </div>
          <div className="new__item__item">
            <CustomInput
              label="Range Max."
              value={rangemax}
              type="number"
              required={true}
              onchange={(v) => setRangeMax(parseInt(v))}
            />
          </div>
          <div className="new__item__item">
            <CustomSelect
              label="Unit"
              value={rangeunit}
              required={true}
              options={unitOptions}
              onselect={(v) => {
                setRangeUnit(v);
              }}
            />
          </div>
          <div className="new__item__item">
            <CustomInput
              label="Serial Number"
              value={serialno}
              type="text"
              required={true}
              onchange={(v) => setSerialNo(v)}
            />
          </div>
          <div className="new__item__item">
            <CustomInput
              label="Id Number"
              value={idno}
              type="text"
              required={true}
              onchange={(v) => setIdno(v)}
            />
          </div>
          <div className="new__item__item">
            <CustomTextArea
              label="Remarks"
              value={remarks}
              onchange={(v) => setRemarks(v)}
              rows={5}
              required={true}
              disabled={false}
            />
          </div>
          <div className="new__item__item">
            <CustomInput
              label="ULR Number"
              value={ulrno}
              type="text"
              required={true}
              onchange={(v) => setULRNo(v)}
            />
          </div>
        </div>
      </Modal>
    </div>
  );
};

export default AddItem;
