import "./AddSRF.css";
import { Card, CheckboxToggle, Spinner } from "react-rainbow-components";
import { useContext, useEffect, useState } from "react";

import CustomDatePicker from "../../Inputs/CustomDatePicker";
import CustomLookup from "../../Inputs/CustomLookup";
import CustomButton from "../../Inputs/CustomButton";
import CustomInput from "../../Inputs/CustomInput";
import CustomTextArea from "../../Inputs/CustomTextArea";
import CustomSelect from "../../Inputs/CustomSelect";
import AddCompany from "../AddCompany/AddCompany";
import { useDispatch, useSelector } from "react-redux";
import { AuthContext } from "../../../context/auth-context";
import config from "../../../utils/config.json";
import { companiesActions } from "../../../store/companies";
import { notificationActions } from "../../../store/nofitication";
import ItemsList from "../ItemsList/ItemsList";
import { srfSchema } from "../../../Schemas/srf";
import { sidebarActions } from "../../../store/sidebar";
import { masterlistActions } from "../../../store/masterlist";

const AddSRF = () => {
  const [srfdate, setSrfDate] = useState(new Date());
  const [company, setCompany] = useState();
  const [contactperson, setContactPerson] = useState("");
  const [contactnumber, setContactNumber] = useState("");
  const [addcompanymodel, setAddCompanyModal] = useState(false);
  const [ruscflag, setRusc] = useState(true);
  const [department, setDepartment] = useState("");
  const [customerdc, setCustomerDC] = useState("");
  const [repcompany, setrepCompany] = useState();
  const [customerdcdate, setCustomerDcDate] = useState();
  const [agreeddate, setagreedDate] = useState();
  const [srfno, setSRFNo] = useState();
  const [contactEmail, setContactEmail] = useState("");
  const [nextcaldueflag, setnextcaldueFlag] = useState(false);
  const [frequency, setFrequency] = useState("0");
  const [statementofconflag, setStatementofConFlag] = useState(false);
  const [statmentofconfirmity, setStatementofConfirmity] = useState("");
  const [uncertainityflag, setUncertainityFlag] = useState(false);
  const [issueno, setIssueNo] = useState("");
  const [issuedate, setIssueDate] = useState();
  const [amendno, setAmendNo] = useState("");
  const [amenddate, setAmendDate] = useState();
  const [sendsrf, setSendSRF] = useState(false);
  const companies = useSelector((state) => state.companies.list);
  //const [companies, setCompanies] = useState([]);
  const auth = useContext(AuthContext);
  const dispatch = useDispatch();
  const [error, setError] = useState("");
  const [isLoaded, setIsLoaded] = useState(true);
  const items = useSelector((state) => state.items.list);
  const [type, setType] = useState("I");
  const types = [
    { label: "I", value: "I" },
    { label: "N", value: "N" },
    { label: "S", value: "S" },
  ];
  useEffect(() => {
    const requestOptions = {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + auth.token,
      },
      body: JSON.stringify({ labId: auth.labId }),
    };
    const errornotification = {
      title: "Error while getting MasterList!!",
      description: "Getting masterlist from server failed!!",
      icon: "error",
      state: true,
      timeout: 15000,
    };
    fetch(config.SERVER.URL + "/api/masterlist/getall", requestOptions)
      .then(async (response) => {
        const data = await response.json();
        setIsLoaded(true);
        ////console.log(data);
        if (data) {
          if (data.code === 200) {
            ////console.log(data);
            let oldmasterlist = data.data;
            const modified = oldmasterlist.map((v, i) => {
              return { id: v.id, sno: i + 1, name: v.name };
            });
            dispatch(masterlistActions.changeitems(modified));
          } else {
            setError(data.message);
            const newNotification = {
              title: "Getting Masterlist Failed!!",
              description: data.message,
              icon: "error",
              state: true,
            };
            dispatch(notificationActions.changenotification(newNotification));
          }
        } else {
          setError("Error While Getting Masterlist!!");
        }
      })
      .catch((err) => {
        setIsLoaded(true);
        setError("Error While Getting Masterlist!!");
      });
  }, []);
  useEffect(() => {
    setError();
  }, [
    srfno,
    srfdate,
    company,
    contactperson,
    contactnumber,
    contactEmail,
    department,
    repcompany,
    customerdc,
    customerdcdate,
    agreeddate,
    nextcaldueflag,
    frequency,
    statementofconflag,
    statmentofconfirmity,
    uncertainityflag,
    sendsrf,
    issueno,
    issuedate,
    amendno,
    amenddate,
  ]);
  useEffect(() => {
    const requestOptions = {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + auth.token,
      },
      body: JSON.stringify({ labId: auth.labId }),
    };
    const errornotification = {
      title: "Error while getting Companies!!",
      description: "Getting list of companies from server failed!!",
      icon: "error",
      state: true,
      timeout: 15000,
    };
    fetch(config.SERVER.URL + "/api/company/getall", requestOptions)
      .then(async (response) => {
        const data = await response.json();

        if (data) {
          if (data.code === 200) {
            //console.log(data);
            dispatch(companiesActions.changecompanies(data.data));
          } else {
            dispatch(notificationActions.changenotification(errornotification));
          }
        } else {
          dispatch(notificationActions.changenotification(errornotification));
        }
      })
      .catch((err) => {
        dispatch(notificationActions.changenotification(errornotification));
      });
  }, []);

  const addCompanyHandler = () => {
    const isopen = addcompanymodel;
    setAddCompanyModal(!isopen);
  };

  const ruscHandler = () => {
    const ruscnow = ruscflag;
    setRusc(!ruscnow);
  };
  const sendsrfHandler = () => {
    const sendsrfl = sendsrf;
    setSendSRF(!sendsrfl);
  };

  const nextcaldueflagHandler = () => {
    const isset = nextcaldueflag;
    setnextcaldueFlag(!isset);
  };
  const statmentofconfHandler = () => {
    const isset = statementofconflag;
    setStatementofConFlag(!isset);
  };

  const uncertainityflagHandler = () => {
    const isset = uncertainityflag;
    setUncertainityFlag(!isset);
  };

  const addsrfHandler = async () => {
    setIsLoaded(false);
    let reportcompany;
    if (ruscflag) {
      reportcompany = company;
    } else {
      if (repcompany) {
        reportcompany = repcompany;
      } else {
        setIsLoaded(true);
        setError("Report Company Not Selected");
        return;
      }
    }
    if (!company || !reportcompany) {
      setIsLoaded(true);
      setError("Company Not Selected");
      return;
    }
    const valsrf = {
      type: type,
      symbol: auth.symbol,
      srfdate,
      srfno: parseInt(srfno),
      company_id: company.id,
      contactperson,
      contactnumber,
      contactemail: contactEmail,
      department,
      reportcompany_id: reportcompany.id,
      customerdc,
      customerdcdate,
      agreeddate,
      nextcaldueflag,
      frequency,
      statementofconflag,
      statmentofconfirmity,
      uncertainityflag,
      issueno,
      issuedate,
      amendno,
      amenddate,
      sendsrf,
    };

    const isValid = await srfSchema.isValid(valsrf);
    if (!isValid) {
      setIsLoaded(true);
      setError("Input Validation Failed!!");
      return;
    }

    const newsrf = {
      srfno: parseInt(srfno),
      type: type,
      symbol: auth.symbol,
      date: srfdate,
      CompanyId: company.id,
      contact_name: contactperson,
      contact_number: contactnumber,
      contact_email: contactEmail,
      department: department,
      reportcompanyId: reportcompany.id,
      customer_dc: customerdc,
      customer_dc_date: customerdcdate,
      agreed_date: agreeddate,
      next_cal_due_require_flag: nextcaldueflag,
      frequency: frequency,
      statement_of_confirmity_flag: statementofconflag,
      statement_of_confirmity: statmentofconfirmity,
      uncertainity_consider_flag: uncertainityflag,
      issue_no: issueno,
      issue_date: issuedate,
      amend_no: amendno,
      amend_date: amenddate,
      sendsrf,
    };
    const requestBody = {
      srf: newsrf,
      items: items,
      labId: auth.labId,
    };
    const requestOptions = {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + auth.token,
      },
      body: JSON.stringify(requestBody),
    };
    const errornotification = {
      title: "Error while Adding SRF!!",
      description: "Adding SRF Failed!!",
      icon: "error",
      state: true,
      timeout: 15000,
    };
    fetch(config.SERVER.URL + "/api/srf/add", requestOptions)
      .then(async (response) => {
        const data = await response.json();

        if (data) {
          if (data.code === 200) {
            const newnotification = {
              title: "SRF Added Successfully!!",
              description: "SRF No: " + data.srfno,
              icon: "success",
              state: true,
              timeout: 15000,
            };
            setIsLoaded(true);
            dispatch(notificationActions.changenotification(newnotification));
            dispatch(sidebarActions.changesidebar("SRFs"));
          } else {
            setIsLoaded(true);
            errornotification.description = data.message;
            dispatch(notificationActions.changenotification(errornotification));
          }
        } else {
          setIsLoaded(true);
          dispatch(notificationActions.changenotification(errornotification));
        }
      })
      .catch((err) => {
        setIsLoaded(true);
        dispatch(notificationActions.changenotification(errornotification));
      });
  };

  return (
    <div className="add__srf__container">
      <div className="add__srf__form__container">
        <Card className="add__srf__card">
          {/*<p>Add SRF Content</p>*/}

          <div className="add__srf__label">
            <h3>New SRF</h3>
          </div>
          <div className="add__srf__item__container">
            <CustomSelect
              options={types}
              onselect={(v) => setType(v)}
              label={"SRF Type"}
              required={true}
              value={type}
            />
          </div>
          <div className="add__srf__item__container">
            <CustomInput
              label="SRF Number"
              value={srfno}
              type="number"
              required={true}
              onchange={(v) => setSRFNo(v)}
            />
          </div>
          <div className="add__srf__item__container">
            <CustomDatePicker
              label={"SRF Date"}
              setDate={(v) => setSrfDate(v)}
              date={srfdate}
              required={true}
            />
          </div>
          <div className="add__srf__item__container">
            <CustomLookup
              options={companies}
              onselect={(v) => setCompany(v)}
              label={"Company"}
              required={true}
            />
          </div>
          <div className="add__srf__item__container">
            <CustomTextArea
              label="Company Address"
              value={
                company
                  ? company.address1 +
                    ", " +
                    company.address2 +
                    ", " +
                    company.address3
                  : ""
              }
              rows={5}
              required={true}
              disabled={true}
            />
          </div>
          <div className="add__srf__item__container">
            <CustomInput
              label="Contact Person Name"
              value={contactperson}
              type="text"
              required={true}
              onchange={(v) => setContactPerson(v)}
            />
          </div>
          <div className="add__srf__item__container">
            <CustomInput
              label="Contact Person Number"
              value={contactnumber}
              type="number"
              min={10}
              max={10}
              required={true}
              onchange={(v) => setContactNumber(v)}
            />
          </div>
          <div className="add__srf__item__container">
            <CustomInput
              label="Email"
              value={contactEmail}
              type="text"
              required={true}
              onchange={(v) => setContactEmail(v)}
            />
          </div>
          <div className="add__srf__item__container">
            <CheckboxToggle
              label="Send SRF through Email"
              value={sendsrf}
              onChange={sendsrfHandler}
            />
          </div>
          <div className="add__srf__item__container">
            <CheckboxToggle
              label="Report under Same Company"
              value={ruscflag}
              onChange={ruscHandler}
            />
          </div>
          {!ruscflag ? (
            <div className="add__srf__item__container">
              <CustomLookup
                options={companies}
                onselect={(v) => setrepCompany(v)}
                label={"Report Company Name"}
                required={true}
              />
            </div>
          ) : null}
          {!ruscflag ? (
            <div className="add__srf__item__container">
              <CustomTextArea
                label="Report Company Address"
                value={
                  repcompany
                    ? repcompany.address1 +
                      ", " +
                      repcompany.address2 +
                      ", " +
                      repcompany.address3
                    : ""
                }
                rows={5}
                required={true}
                disabled={true}
              />
            </div>
          ) : null}
          <div className="add__srf__item__container">
            <CustomInput
              label="Department"
              value={department}
              type="text"
              required={true}
              onchange={(v) => setDepartment(v)}
            />
          </div>
          <div className="add__srf__item__container">
            <CustomInput
              label="Customer DC No"
              value={customerdc}
              type="text"
              required={true}
              onchange={(v) => setCustomerDC(v)}
            />
          </div>
          <div className="add__srf__item__container">
            <CustomDatePicker
              label={"Customer DC Date"}
              setDate={(v) => setCustomerDcDate(v)}
              date={customerdcdate}
              required={true}
              maxDate={srfdate}
            />
          </div>
          <div className="add__srf__item__container">
            <CustomDatePicker
              label={"Agreed Date of Completion"}
              setDate={(v) => setagreedDate(v)}
              date={agreeddate}
              required={true}
              minDate={srfdate}
            />
          </div>
          <div className="add__srf__item__container">
            <CheckboxToggle
              label="Next Calibration Due Date require in certificate"
              value={nextcaldueflag}
              onChange={nextcaldueflagHandler}
            />
          </div>
          {nextcaldueflag ? (
            <div className="add__srf__item__container">
              <CustomInput
                label="Frequency in Months"
                type="number"
                onchange={(v) => setFrequency(v)}
                value={frequency}
              />
            </div>
          ) : null}
          <div className="add__srf__item__container">
            <CheckboxToggle
              label="Statement of confirmity"
              value={statementofconflag}
              onChange={statmentofconfHandler}
            />
          </div>
          {statementofconflag ? (
            <div className="add__srf__item__container">
              <CustomTextArea
                label="Statement of Confirmity"
                value={statmentofconfirmity}
                onchange={(v) => setStatementofConfirmity(v)}
                rows={5}
                required={true}
                disabled={false}
              />
            </div>
          ) : null}
          <div className="add__srf__item__container">
            <CheckboxToggle
              label="Uncertainty should be consider for the declaration of statement of the confirmity "
              value={uncertainityflag}
              onChange={uncertainityflagHandler}
            />
          </div>
          <div className="add__srf__item__container">
            <CustomInput
              label="Issue No"
              value={issueno}
              type="text"
              required={true}
              onchange={(v) => setIssueNo(v)}
            />
          </div>
          <div className="add__srf__item__container">
            <CustomDatePicker
              label={"Issue Date"}
              setDate={(v) => setIssueDate(v)}
              date={issuedate}
              required={true}
            />
          </div>
          <div className="add__srf__item__container">
            <CustomInput
              label="Amend No"
              value={amendno}
              type="text"
              required={true}
              onchange={(v) => setAmendNo(v)}
            />
          </div>
          <div className="add__srf__item__container">
            <CustomDatePicker
              label={"Amend Date"}
              setDate={(v) => setAmendDate(v)}
              date={amenddate}
              required={true}
            />
          </div>
          <div className="add__srf__item__container">
            <CustomButton
              label="Add Company"
              onclick={addCompanyHandler}
              variant="brand"
            />
          </div>
          {addcompanymodel ? (
            <AddCompany onclose={addCompanyHandler} isopen={addcompanymodel} />
          ) : null}
          <p className="red center w_100">{error}</p>
        </Card>
      </div>
      <ItemsList addsrf={addsrfHandler} />
      {!isLoaded ? <Spinner size="medium" /> : null}
    </div>
  );
};

export default AddSRF;
