import "./Labs.css";
import CustomInput from "../../Inputs/CustomInput";
import { useContext, useState, useEffect } from "react";
import { Card, Spinner } from "react-rainbow-components";
import CustomButton from "../../Inputs/CustomButton";
import { AuthContext } from "../../../context/auth-context";
import { useDispatch } from "react-redux";
import { notificationActions } from "../../../store/nofitication";
import config from "../../../utils/config.json";
import CustomFilePicker from "../../Inputs/CustomFilePicker";
import { labSchema } from "../../../Schemas/lab";
import { getBase64 } from "../../../utils/utilfuns";
const Labs = (props) => {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [address1, setAddress1] = useState("");
  const [address2, setAddress2] = useState("");
  const [address3, setAddress3] = useState("");
  const [contactNumber, setContactNumber] = useState();
  const [symbol, setSymbol] = useState("");
  const [limageName, setLImageName] = useState();
  const [limageType, setLImageType] = useState();
  const [limageData, setLImageData] = useState();
  const [limageSize, setLImageSize] = useState();
  const [adminName, setAdminName] = useState();
  const [adminEmail, setAdminEmail] = useState();
  const [adminPassword, setAdminPassword] = useState();
  const auth = useContext(AuthContext);
  const [error, setError] = useState();
  const [isLoaded, setIsLoaded] = useState(true);
  const dispatch = useDispatch();

  useEffect(() => {
    setError();
  }, [
    name,
    email,
    address1,
    address2,
    address3,
    symbol,
    contactNumber,
    limageName,
    limageData,
  ]);

  const lhandler = (v) => {
    if (v && v[0]) {
      if (
        v[0].type == "image/png" ||
        v[0].type == "image/jpeg" ||
        v[0].type == "image/jpg"
      ) {
        if (v[0].size < 60000) {
          setLImageSize(v[0].size);
          setLImageName(v[0].name);
          setLImageType(v[0].type);
          getBase64(v[0], (result) => {
            //console.log(result);
            setLImageData(result);
          });
        } else {
          setError("File size not allowed!! Please select file below 50kb!!");
        }
      } else {
        setError("File type not allowed!! Please select jpeg, jpg, png file!!");
      }
    }
  };
  const addLabHandler = async () => {
    setIsLoaded(false);

    const newlab = {
      name,
      email,
      address1,
      address2,
      address3,
      symbol,
      contactNumber,
      limageName,
      limageType,
      limageData,
      limageSize,
      adminName,
      adminEmail,
      adminPassword,
    };

    const isValid = await labSchema.isValid(newlab);
    if (!isValid) {
      setError("Input Validation Failed!! Please Check!!");
      setIsLoaded(true);
      return;
    }
    const requestOptions = {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + auth.token,
      },
      body: JSON.stringify(newlab),
    };
    //console.log(requestOptions);
    const errornotification = {
      title: "Error while Adding Lab!!",
      description: "Adding new Lab failed!!",
      icon: "error",
      state: true,
      timeout: 15000,
    };
    fetch(config.SERVER.URL + "/api/lab/new", requestOptions)
      .then(async (response) => {
        const data = await response.json();
        setIsLoaded(true);
        //console.log(data);
        if (data) {
          if (data.code === 200) {
            const newNotification = {
              title: "Lab Added Successfully",
              description: name,
              icon: "success",
              state: true,
              timeout: 15000,
            };
            dispatch(notificationActions.changenotification(newNotification));
          } else {
            setError(data.message);
            const newNotification = {
              title: "Adding Lab Failed!!",
              description: name,
              icon: "error",
              state: true,
            };
            dispatch(notificationActions.changenotification(newNotification));
          }
        } else {
          setError("Error While Adding Lab!!");
          dispatch(notificationActions.changenotification(errornotification));
        }
      })
      .catch((err) => {
        setIsLoaded(true);
        setError("Error While Adding Lab!!!");
        dispatch(notificationActions.changenotification(errornotification));
      });
  };
  return (
    <div className="add__lab__container">
      <Card className="add__lab__card">
        <div className="add__lab__label">
          <h3>Add new Lab</h3>
        </div>
        <div className="add__lab__form">
          <div className="add__lab__item">
            <CustomInput
              label="Lab Name"
              type="text"
              value={name}
              onchange={(v) => setName(v)}
              disabled={false}
              required={true}
            />
          </div>
          <div className="add__lab__item">
            <CustomInput
              label="Address 1"
              type="text"
              value={address1}
              onchange={(v) => setAddress1(v)}
              disabled={false}
              required={true}
            />
          </div>
          <div className="add__lab__item">
            <CustomInput
              label="Address 2"
              type="text"
              value={address2}
              onchange={(v) => setAddress2(v)}
              disabled={false}
              required={true}
            />
          </div>
          <div className="add__lab__item">
            <CustomInput
              label="Address 3"
              type="text"
              value={address3}
              onchange={(v) => setAddress3(v)}
              disabled={false}
              required={true}
            />
          </div>
          <div className="add__lab__item">
            <CustomInput
              label="Email"
              type="text"
              value={email}
              onchange={(v) => setEmail(v)}
              disabled={false}
              required={true}
            />
          </div>
          <div className="add__lab__item">
            <CustomInput
              label="Contact Number"
              type="number"
              value={contactNumber}
              onchange={(v) => setContactNumber(v)}
              disabled={false}
              required={true}
            />
          </div>
          <div className="add__lab__item">
            <CustomInput
              label="Symbol"
              type="text"
              value={symbol}
              onchange={(v) => setSymbol(v)}
              disabled={false}
              required={true}
            />
          </div>
          <div className="add__lab__item">
            <CustomFilePicker
              label="Logo"
              placeholder="Select or Drag and Drop image file"
              helptext="Select only one jpeg or png file. File size should be less than 50kb"
              required={true}
              onchange={lhandler}
            />
          </div>
          <div className="add__lab__label">
            <h3>Admin Details</h3>
          </div>
          <div className="add__lab__item">
            <CustomInput
              label="Admin Name"
              type="text"
              value={adminName}
              onchange={(v) => setAdminName(v)}
              disabled={false}
              required={true}
            />
          </div>
          <div className="add__lab__item">
            <CustomInput
              label="Admin Email"
              type="text"
              value={adminEmail}
              onchange={(v) => setAdminEmail(v)}
              disabled={false}
              required={true}
            />
          </div>
          <div className="add__lab__item">
            <CustomInput
              label="Admin Password"
              type="password"
              value={adminPassword}
              onchange={(v) => setAdminPassword(v)}
              disabled={false}
              required={true}
            />
          </div>
          <p className="red center w100">{error}</p>
          {!isLoaded ? <Spinner size="medium" /> : null}
          <div className="add__lab__btn">
            <CustomButton
              label="Add Lab"
              variant="success"
              onclick={addLabHandler}
            />
          </div>
        </div>
      </Card>
    </div>
  );
};

export default Labs;
