import "./Email.css";
import { Card, Spinner, CheckboxToggle } from "react-rainbow-components";
import { useState, useEffect, useContext } from "react";
import CustomInput from "../../Inputs/CustomInput";
import CustomButton from "../../Inputs/CustomButton";
import { AuthContext } from "../../../context/auth-context";
import { useDispatch } from "react-redux";
import { notificationActions } from "../../../store/nofitication";
import config from "../../../utils/config.json";
import { emailconfigSchema } from "../../../Schemas/emailconfig";
const Email = () => {
  const [email, setEmail] = useState();
  const [password, setPassword] = useState();
  const [host, setHost] = useState();
  const [port, setPort] = useState(0);
  const auth = useContext(AuthContext);
  const [error, setError] = useState();
  const [isLoaded, setIsLoaded] = useState(true);
  const [testmailFlag, setTestMailFlag] = useState(false);
  const [remail, setREmail] = useState();
  const dispatch = useDispatch();

  useEffect(() => {
    setError();
  }, [email, password, host, port]);

  const testmailFlagHandler = () => {
    const testmailflag = testmailFlag;
    setTestMailFlag(!testmailflag);
  };

  const updateEmailHandler = async () => {
    setIsLoaded(false);
    const portn = parseInt(port);
    const emailconfig = {
      email,
      password,
      host,
      port: portn,
    };
    const isValid = await emailconfigSchema.isValid(emailconfig);
    if (!isValid) {
      setError("Input Validation Failed!! Please Check!!");
      setIsLoaded(true);
      return;
    }
    const requestOptions = {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + auth.token,
      },
      body: JSON.stringify({ emailconfig, labId: auth.labId }),
    };
    //console.log(requestOptions);
    const errornotification = {
      title: "Update Failed!!",
      description: "Email Configuration Update Failed!!",
      icon: "error",
      state: true,
      timeout: 15000,
    };
    fetch(config.SERVER.URL + "/api/lab/emailconfig", requestOptions)
      .then(async (response) => {
        const data = await response.json();
        setIsLoaded(true);
        //console.log(data);
        if (data) {
          if (data.code === 200) {
            const newNotification = {
              title: "Updated Successfully!!",
              description: "Email Configuration Updated Successfully!!",
              icon: "success",
              state: true,
              timeout: 15000,
            };
            dispatch(notificationActions.changenotification(newNotification));
          } else {
            setError(data.message);

            dispatch(notificationActions.changenotification(errornotification));
          }
        } else {
          setError("Error While Updating Email Configuration!!");
          dispatch(notificationActions.changenotification(errornotification));
        }
      })
      .catch((err) => {
        setIsLoaded(true);
        setError("Error While Updating Email Configuration!!");
        dispatch(notificationActions.changenotification(errornotification));
      });
  };
  const testMailHandler = async () => {
    setIsLoaded(false);
    const portn = parseInt(port);
    const emailconfig = {
      email,
      password,
      host,
      port: portn,
      remail,
    };
    const isValid = await emailconfigSchema.isValid(emailconfig);
    if (!isValid) {
      setError("Input Validation Failed!! Please Check!!");
      setIsLoaded(true);
      return;
    }
    const requestOptions = {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + auth.token,
      },
      body: JSON.stringify({ emailconfig, labId: auth.labId }),
    };
    //console.log(requestOptions);
    const errornotification = {
      title: "Error While Sending Test Email!!",
      description: "Please check the Entered Parameters!!",
      icon: "error",
      state: true,
      timeout: 15000,
    };
    fetch(config.SERVER.URL + "/api/lab/testmail", requestOptions)
      .then(async (response) => {
        const data = await response.json();
        setIsLoaded(true);
        //console.log(data);
        if (data) {
          if (data.code === 200) {
            const newNotification = {
              title: "Test Email Sent Successfully!!",
              description: "Please check Receiver Inbox!!",
              icon: "success",
              state: true,
              timeout: 15000,
            };
            dispatch(notificationActions.changenotification(newNotification));
          } else {
            setError(data.message);

            dispatch(notificationActions.changenotification(errornotification));
          }
        } else {
          setError("Error While Sending Test Email!!");
          dispatch(notificationActions.changenotification(errornotification));
        }
      })
      .catch((err) => {
        setIsLoaded(true);
        setError("Error While Sending Test Email!!");
        dispatch(notificationActions.changenotification(errornotification));
      });
  };
  return (
    <div className="email__page">
      <Card className="email__page__card">
        <div className="email__page__label">
          <h3>Email Configuration</h3>
        </div>
        <div className="email__page__form">
          <div className="email__page__item">
            <CustomInput
              label="Email Address"
              type="text"
              value={email}
              onchange={(v) => setEmail(v)}
              disabled={false}
              required={true}
            />
          </div>
          <div className="email__page__item">
            <CustomInput
              label="Password"
              type="password"
              value={password}
              onchange={(v) => setPassword(v)}
              disabled={false}
              required={true}
            />
          </div>
          <div className="email__page__item">
            <CustomInput
              label="Host"
              type="text"
              value={host}
              onchange={(v) => setHost(v)}
              disabled={false}
              required={true}
            />
          </div>
          <div className="email__page__item">
            <CustomInput
              label="Port"
              type="number"
              value={port}
              onchange={(v) => setPort(v)}
              disabled={false}
              required={true}
            />
          </div>
          <div className="email__page__item__special">
            <CheckboxToggle
              label="Send a Test Mail"
              value={testmailFlag}
              onChange={testmailFlagHandler}
            />
          </div>
          {testmailFlag ? (
            <div className="email__page__item">
              <CustomInput
                label="Receiver Email Address"
                type="text"
                value={remail}
                onchange={(v) => setREmail(v)}
                disabled={false}
                required={false}
              />
            </div>
          ) : null}
          {testmailFlag ? (
            <div className="email__page__item__special">
              <CustomButton
                label="Send Test Mail"
                variant="brand"
                onclick={testMailHandler}
              />
            </div>
          ) : null}
          <p className="red center w100">{error}</p>
          {!isLoaded ? <Spinner size="medium" /> : null}
          <div className="email__page__btn">
            <CustomButton
              label="Update Email Details"
              variant="success"
              onclick={updateEmailHandler}
            />
          </div>
        </div>
      </Card>
    </div>
  );
};

export default Email;
