import { useContext, useEffect, useState } from "react";
import {
  TableWithBrowserPagination,
  Column,
  Button,
  Spinner,
} from "react-rainbow-components";
import { useDispatch, useSelector } from "react-redux";
import "./UsersList.css";
import { AuthContext } from "../../../context/auth-context";
import config from "../../../utils/config.json";
import { notificationActions } from "../../../store/nofitication";
import { usersActions } from "../../../store/users";
import EditUserModal from "./EditUserModal";
import CustomSearch from "../../Inputs/CustomSearch";

const UsersList = (props) => {
  const users = useSelector((state) => state.users.list);
  const dispatch = useDispatch();
  const [modifiedUsers, setModifiedUsers] = useState();
  const [isLoaded, setIsLoaded] = useState(true);
  const [editUserModal, setEditUserModal] = useState(false);
  const [editId, setEditId] = useState();
  const auth = useContext(AuthContext);
  const [filteredUsers, setFilteredUsers] = useState();

  useEffect(() => {
    if (users) {
      const modifiedusers = users.map((v, i) => ({
        ...v,
        sno: i + 1,
      }));
      setModifiedUsers(modifiedusers);
    }
  }, [users]);
  useEffect(() => {
    setIsLoaded(false);
    const requestOptions = {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + auth.token,
      },
      body: JSON.stringify({ labId: auth.labId }),
    };
    const errornotification = {
      title: "Error while Getting Users!!",
      description: "Getting List of Users Failed!!",
      icon: "error",
      state: true,
      timeout: 15000,
    };

    fetch(config.SERVER.URL + "/api/users/getall", requestOptions)
      .then(async (response) => {
        const data = await response.json();

        if (data) {
          if (data.code === 200) {
            setIsLoaded(true);
            dispatch(usersActions.changeusers(data.data));
          } else {
            setIsLoaded(true);
            errornotification.description = data.message;
            dispatch(notificationActions.changenotification(errornotification));
          }
        } else {
          setIsLoaded(true);
          dispatch(notificationActions.changenotification(errornotification));
        }
      })
      .catch((err) => {
        setIsLoaded(true);
        dispatch(notificationActions.changenotification(errornotification));
      });
  }, []);
  const userdeleteHandler = async (v) => {
    setIsLoaded(false);
    const requestOptions = {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + auth.token,
      },
      body: JSON.stringify({ userId: v, labId: auth.labId }),
    };
    const errornotification = {
      title: "Error while Deleting User!!",
      description: "UserId: " + v,
      icon: "error",
      state: true,
      timeout: 15000,
    };
    fetch(config.SERVER.URL + "/api/users/deleteuser", requestOptions)
      .then(async (response) => {
        const data = await response.json();
        setIsLoaded(true);
        console.log(data);
        if (data) {
          if (data.code === 200) {
            const newNotification = {
              title: "User Deleted Successfully",
              description: "UserId: " + v,
              icon: "success",
              state: true,
              timeout: 15000,
            };
            //console.log(data);
            dispatch(usersActions.changeusers(data.data));
            dispatch(notificationActions.changenotification(newNotification));
          } else {
            dispatch(notificationActions.changenotification(errornotification));
          }
        } else {
          dispatch(notificationActions.changenotification(errornotification));
        }
      })
      .catch((err) => {
        dispatch(notificationActions.changenotification(errornotification));
      });
  };
  const userEditHandler = (v) => {
    setEditUserModal(true);
    setEditId(v);
  };

  const editmodalHandler = () => {
    const usereditmodal = editUserModal;
    setEditUserModal(!usereditmodal);
  };
  const EditUser = ({ value }) => (
    <Button
      variant="neutral"
      label="Edit"
      onClick={() => userEditHandler(value)}
    />
  );
  const DeleteUser = ({ value }) => (
    <Button
      variant="destructive"
      label="Delete"
      onClick={() => userdeleteHandler(value)}
    />
  );
  return (
    <div className="users__container">
      <div className="searchers__container">
        <div className="searchers">
          <CustomSearch
            options={modifiedUsers}
            onfilter={(v) => setFilteredUsers(v)}
            filterby="id"
            label="Search By Id"
          />
        </div>
        <div className="searchers">
          <CustomSearch
            options={modifiedUsers}
            onfilter={(v) => setFilteredUsers(v)}
            filterby="name"
            label="Search By Name"
          />
        </div>
        <div className="searchers">
          <CustomSearch
            options={modifiedUsers}
            onfilter={(v) => setFilteredUsers(v)}
            filterby="email"
            label="Search By Email"
          />
        </div>
        <div className="searchers">
          <CustomSearch
            options={modifiedUsers}
            onfilter={(v) => setFilteredUsers(v)}
            filterby="department"
            label="Search By Department"
          />
        </div>
      </div>
      <TableWithBrowserPagination
        className="users__table"
        pageSize={5}
        data={filteredUsers ? filteredUsers : modifiedUsers}
        keyField="sno"
      >
        <Column header="S.No" field="sno" />
        <Column header="User Id" field="id" />
        <Column header="Name" field="name" />
        <Column header="Email" field="email" />
        <Column header="Department" field="department" />
        <Column header="Edit" field="id" component={EditUser} />
        <Column header="Delete" field="id" component={DeleteUser} />
      </TableWithBrowserPagination>
      {!isLoaded ? <Spinner size="medium" /> : null}
      {editUserModal ? (
        <EditUserModal
          isopen={editUserModal}
          onclose={editmodalHandler}
          userid={editId}
        />
      ) : null}
    </div>
  );
};

export default UsersList;
