import * as yup from "yup";

export const labSchema = yup.object().shape({
  name: yup.string().min(5).required(),
  email: yup.string().email().required(),
  address1: yup.string().min(3).required(),
  address2: yup.string().min(3).required(),
  address3: yup.string().min(3).required(),
  contactNumber: yup.number().min(10).required(),
  symbol: yup.string().min(2).required(),
  limageName: yup.string().required(),
  limageType: yup.string().required(),
  limageSize: yup.number().required(),
  adminName: yup.string().min(5).required(),
  adminEmail: yup.string().email().required(),
  adminPassword: yup.string().min(8).required(),
});
