import "./EditSRFItem.css";

import { Spinner, Button, Modal } from "react-rainbow-components";
import CustomInput from "../../Inputs/CustomInput";
import CustomTextArea from "../../Inputs/CustomTextArea";
import CustomSelect from "../../Inputs/CustomSelect";
import { useContext, useState } from "react";
import { itemSchema } from "../../../Schemas/item";
import { useDispatch } from "react-redux";
import { notificationActions } from "../../../store/nofitication";
import { AuthContext } from "../../../context/auth-context";
import config from "../../../utils/config.json";
import { srfitemsActions } from "../../../store/srfitems";
const unitoptions = [
  { label: "mm", value: "mm" },
  { label: "cm", value: "cm" },
];
const EditSRFItem = (props) => {
  const [isLoaded, setisLoaded] = useState(true);

  const [ulrno, setULRNo] = useState();
  const [error, setError] = useState("");
  const [description, setDescription] = useState(props.item.description);
  const [make, setMake] = useState(props.item.make);
  const [model, setModel] = useState(props.item.model);
  const [range, setRange] = useState(props.item.range);
  const [serialno, setSerialNo] = useState(props.item.serialno);
  const [idno, setIdno] = useState(props.item.idno);
  const [remarks, setRemarks] = useState(props.item.remarks);
  const [rangemin, setRangeMin] = useState(props.item.range_min);
  const [rangemax, setRangeMax] = useState(props.item.range_max);
  const [rangeunit, setRangeUnit] = useState(props.item.range_unit);
  const dispatch = useDispatch("");
  const auth = useContext(AuthContext);
  //console.log(props.item);
  const updateitemHandler = async () => {
    setisLoaded(false);
    const newitem = {
      sno: props.item.sno,
      description,
      make,
      model,
      range_min: rangemin,
      range_max: rangemax,
      range_unit: rangeunit,
      serialno,
      idno,
      remarks,
      ulrno,
      masterlistId: props.item.masterlistId,
    };
    //console.log(newitem);
    const isValid = await itemSchema.isValid(newitem);
    if (!isValid) {
      setError("Input Validation Failed!! Please Check!!");
      setisLoaded(true);
      return;
    }
    const newNotification = {
      title: "Item Updated Successfully",
      description: description,
      icon: "info",
      state: true,
      timeout: 10000,
    };
    const requestBody = {
      id: props.item.id,
      srfId: props.item.srfId,
      item: newitem,
    };
    const requestOptions = {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + auth.token,
      },
      body: JSON.stringify(requestBody),
    };
    const errornotification = {
      title: "Error while Updating SRF Item!!",
      description: "Updating SRF Item Failed!!",
      icon: "error",
      state: true,
      timeout: 15000,
    };
    fetch(config.SERVER.URL + "/api/srf/updateitem", requestOptions)
      .then(async (response) => {
        const data = await response.json();

        if (data) {
          if (data.code === 200) {
            //console.log(data);
            const newnotification = {
              title: "SRF Item Updated Successfully!!",
              description: "SNo: " + props.item.sno,
              icon: "success",
              state: true,
              timeout: 15000,
            };
            setisLoaded(true);
            dispatch(srfitemsActions.changesrfitems(data.data.items));
            dispatch(notificationActions.changenotification(newnotification));
            props.onclose();
          } else {
            setisLoaded(true);
            errornotification.description = data.message;
            dispatch(notificationActions.changenotification(errornotification));
          }
        } else {
          setisLoaded(true);
          dispatch(notificationActions.changenotification(errornotification));
        }
      })
      .catch((err) => {
        setisLoaded(true);
        dispatch(notificationActions.changenotification(errornotification));
      });
  };
  return (
    <div className="new__item__modal__container">
      <Modal
        id="modal-2"
        isOpen={props.isopen}
        onRequestClose={props.onclose}
        title="Edit SRF Item"
        footer={
          <div className="rainbow-flex center">
            <p className="red">{error}</p>
            {!isLoaded ? <Spinner size="medium" /> : null}
            <Button
              label="Update Item"
              variant="brand"
              onClick={updateitemHandler}
            />
          </div>
        }
      >
        <div className="new__item__modal__body">
          <div className="new__item__item">
            <CustomInput
              label="Description of Item"
              value={description}
              type="text"
              required={true}
              disabled={true}
              onchange={(v) => setDescription(v)}
            />
          </div>
          <div className="new__item__item">
            <CustomInput
              label="Make"
              value={make}
              type="text"
              required={true}
              onchange={(v) => setMake(v)}
            />
          </div>
          <div className="new__item__item">
            <CustomInput
              label="Model"
              value={model}
              type="text"
              required={true}
              onchange={(v) => setModel(v)}
            />
          </div>
          <div className="new__item__item">
            <CustomInput
              label="Range Min."
              value={rangemin}
              type="number"
              required={true}
              onchange={(v) => setRangeMin(parseInt(v))}
            />
          </div>
          <div className="new__item__item">
            <CustomInput
              label="Range Max."
              value={rangemax}
              type="number"
              required={true}
              onchange={(v) => setRangeMax(parseInt(v))}
            />
          </div>
          <div className="new__item__item">
            <CustomSelect
              label="Unit"
              value={rangeunit}
              required={true}
              options={unitoptions}
              onselect={(v) => {
                setRangeUnit(v);
              }}
            />
          </div>
          <div className="new__item__item">
            <CustomInput
              label="Serial Number"
              value={serialno}
              type="text"
              required={true}
              onchange={(v) => setSerialNo(v)}
            />
          </div>
          <div className="new__item__item">
            <CustomInput
              label="Id Number"
              value={idno}
              type="text"
              required={true}
              onchange={(v) => setIdno(v)}
            />
          </div>
          <div className="new__item__item">
            <CustomTextArea
              label="Remarks"
              value={remarks}
              onchange={(v) => setRemarks(v)}
              rows={5}
              disabled={false}
            />
          </div>
          <div className="new__item__item">
            <CustomInput
              label="ULR Number"
              value={ulrno}
              type="text"
              required={true}
              onchange={(v) => setULRNo(v)}
            />
          </div>
        </div>
      </Modal>
    </div>
  );
};

export default EditSRFItem;
