import "./UpdateInvoice.css";
import { Modal, Spinner, Button, Card } from "react-rainbow-components";
import { useContext, useEffect, useState } from "react";
import { notificationActions } from "../../../store/nofitication";
import { useDispatch, useSelector } from "react-redux";
import { AuthContext } from "../../../context/auth-context";
import config from "../../../utils/config.json";
import { srfitemsActions } from "../../../store/srfitems";
import SRFItemsListView from "./SRFItemsListView";

const UpdateInvoice = (props) => {
  const [error, setError] = useState();
  const [isLoaded, setIsLoaded] = useState(true);
  const [srf, setSRF] = useState();
  const dispatch = useDispatch();
  const auth = useContext(AuthContext);
  const [title, setTitle] = useState("");
  const selecteditems = useSelector((state) => state.selecteditems.list);

  const getSRFDetail = async () => {
    if (props.srfid) {
      setIsLoaded(false);
      const requestOptions = {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + auth.token,
        },
        body: JSON.stringify({ srfId: props.srfid }),
      };
      const errornotification = {
        title: "Error while Getting SRF Detail!!",
        description: props.srfid,
        icon: "error",
        state: true,
        timeout: 15000,
      };
      fetch(config.SERVER.URL + "/api/srf/getsrfbyid", requestOptions)
        .then(async (response) => {
          const data = await response.json();
          setIsLoaded(true);
          //console.log(data);
          if (data) {
            if (data.code === 200) {
              //console.log(data);
              setSRF(data.data.srf);
              dispatch(srfitemsActions.changesrfitems(data.data.items));
              setIsLoaded(true);
            } else {
              dispatch(
                notificationActions.changenotification(errornotification)
              );
              setError(data.message);
            }
          } else {
            dispatch(notificationActions.changenotification(errornotification));
            setError("Error while Getting SRF Detail!!");
          }
        })
        .catch((err) => {
          dispatch(notificationActions.changenotification(errornotification));
          setError("Error while Getting SRF Detail!!");
        });
    }
  };
  useEffect(() => {
    getSRFDetail();
  }, [props.srfid]);

  useEffect(() => {
    if (props.mode == "updateinvoice") {
      setTitle("Update Invoice Detail!!");
    } else {
      setTitle("Update Payment Status!!");
    }
  }, [props]);

  return (
    <div className="view__srf__modal__container">
      <Modal
        id="view__srf"
        isOpen={props.isopen}
        onRequestClose={props.onclose}
        title={title}
        className="view__srf__modal"
        footer={
          <div className="rainbow-flex center">
            <p className="red w100">{error}</p>
            {!isLoaded ? <Spinner size="medium" /> : null}
          </div>
        }
      >
        {srf ? (
          <div className="srf__container">
            <div className="srf__header__container">
              <div className="srf__header__column">
                <div className="srf__header__item si11">
                  <p className="bold">
                    SRF No: <span className="red">{props.srfNo}</span>
                  </p>
                </div>
                <div className="srf__header__item si12">
                  <p className="bold">
                    SRF Date: <span className="red">{srf.date}</span>
                  </p>
                </div>
                <div className="srf__header__item si13">
                  <p className="bold">
                    Customer DC: <span className="red">{srf.customer_dc}</span>
                  </p>
                </div>
                <div className="srf__header__item si14">
                  <p className="bold">
                    Customer DC Date:
                    <span className="red">{srf.customer_dc_date}</span>
                  </p>
                </div>
              </div>
              <div className="srf__header__column">
                <div className="srf__header__item si21">
                  <p className="bold">
                    Company Name:
                    <span className="red">{srf.Company.companyname}</span>
                  </p>
                </div>
                <div className="srf__header__item si24">
                  <p className="bold">
                    Company Address:
                    <span className="red">
                      {srf.Company.address1 +
                        ", " +
                        srf.Company.address2 +
                        ", " +
                        srf.Company.address3}
                    </span>
                  </p>
                </div>
              </div>
              <div className="srf__header__column">
                <div className="srf__header__item si31">
                  <p className="bold">
                    Contact Person:
                    <span className="red">{srf.contact_name}</span>
                  </p>
                </div>
                <div className="srf__header__item si32">
                  <p className="bold">
                    Contact Number:
                    <span className="red">{srf.contact_number}</span>
                  </p>
                </div>
                <div className="srf__header__item si33">
                  <p className="bold">
                    Department:
                    <span className="red">{srf.department}</span>
                  </p>
                </div>
              </div>

              <div className="srf__header__column">
                <div className="srf__header__item si41">
                  <p className="bold">
                    Report Company Name:
                    <span className="red">{srf.reportcompany.companyname}</span>
                  </p>
                </div>
                <div className="srf__header__item si42">
                  <p className="bold">
                    Report Company Address:
                    <span className="red">
                      {srf.reportcompany.address1 +
                        ", " +
                        srf.reportcompany.address2 +
                        ", " +
                        srf.reportcompany.address3}
                    </span>
                  </p>
                </div>
              </div>
            </div>
            <div className="srf__body__container">
              <SRFItemsListView
                srfId={srf.id}
                checkbox={false}
                onclose={props.onclose}
                mode={props.mode}
              />
            </div>
          </div>
        ) : null}
      </Modal>
    </div>
  );
};
export default UpdateInvoice;
