import "./LoginCard.css";
import React, { useState, useContext } from "react";
import { Card } from "react-rainbow-components";
import styled from "styled-components";
import { AuthContext } from "../../context/auth-context";
import config from "../../utils/config.json";
import { Avatar, Input, Button, Spinner } from "react-rainbow-components";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faArrowRight } from "@fortawesome/free-solid-svg-icons";
//import logo from "../../images/calibmaster.png";
import logo from "../../images/CalibMaster_Logo2.png";
import { userloginSchema } from "../../Schemas/userlogin";
import SimpleReactValidator from "simple-react-validator";

const avatarLarge = { width: 110, height: 110 };
const inputStyles = {
  width: 200,
};

const StyledCard = styled(Card)`
  width: 300px;
  height: 363px;
  opacity: 0.9;
`;

const LoginCard = (props) => {
  const [email, setEmail] = useState();
  const [password, setPassword] = useState();
  const [error, setError] = useState();
  const auth = useContext(AuthContext);
  const [isLoaded, setisLoaded] = useState(true);
  const emailHandler = (e) => {
    var value = e.target.value;
    setEmail(value);
    setError();
  };

  const passwordHandler = (e) => {
    var value = e.target.value;
    setPassword(value);
    setError();
  };

  const loginHandler = async () => {
    setisLoaded(false);
    const requestBody = {
      email,
      password,
    };
    const isValid = await userloginSchema.isValid(requestBody);
    if (!isValid) {
      setError("Input Validation Failed!!");
      setisLoaded(true);
      return;
    }
    const requestOptions = {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(requestBody),
    };
    fetch(config.SERVER.URL + "/api/users/login", requestOptions)
      .then(async (response) => {
        const data = await response.json();
        setisLoaded(true);
        //console.log(data);

        if (data) {
          if (data.code === 200) {
            const data1 = data.data;
            if (data1.email != "root@iviewsense.com") {
              const prefix = "data:" + data1.imgtype + ";base64,";
              const base64data = new Buffer(data.data.image).toString("base64");
              localStorage.setItem("logo", prefix + base64data);
            }

            auth.login(
              data1.userId,
              data1.token,
              data1.name,
              data1.email,
              data1.department,
              data1.labId
            );
            setError();
            props.redirect(true);
          } else {
            setError(data.message);
          }
        }
      })
      .catch((error) => {
        setisLoaded(true);
        setError(error.message);
      });
  };
  return (
    <div className="centered">
      <StyledCard
        className="rainbow-flex
        rainbow-flex_column 
        rainbow-align_center 
        rainbow-justify_space-around 
        rainbow-p-vertical_small 
        rainbow-m-around_small flex-center login__card"
      >
        <div className="flex-center">
          <Avatar
            style={avatarLarge}
            src={logo}
            assistiveText="logo"
            title="logo"
          />
          <div className="topgap">
            <Input
              label="Email"
              placeholder="Email"
              type="email"
              className="rainbow-p-around_medium"
              style={inputStyles}
              onChange={emailHandler}
            />
            {isLoaded ? null : <Spinner size="medium" />}
            <Input
              label="Password"
              placeholder="**********"
              type="password"
              className="rainbow-p-around_medium"
              style={inputStyles}
              onChange={passwordHandler}
            />
          </div>
          <div className="topgap">
            <Button
              variant="brand"
              className="rainbow-m-around_medium"
              onClick={loginHandler}
            >
              Login &nbsp;
              <FontAwesomeIcon
                icon={faArrowRight}
                className="rainbow-m-left_medium"
              />
            </Button>
          </div>
        </div>

        <p className="redcolor">{error}</p>
      </StyledCard>
    </div>
  );
};

export default LoginCard;
