import "./SRFsList.css";

import { useContext, useEffect, useState } from "react";
import {
  TableWithBrowserPagination,
  Column,
  Button,
  Spinner,
} from "react-rainbow-components";
import { useDispatch, useSelector } from "react-redux";
import { AuthContext } from "../../../context/auth-context";
import config from "../../../utils/config.json";
import { notificationActions } from "../../../store/nofitication";
import { srfsActions } from "../../../store/srfs";
import CustomSearch from "../../Inputs/CustomSearch";
import ViewSRFModal from "./ViewSRFModal";
import { filteredsrfsActions } from "../../../store/filteredsrfs";

const SRFsList = (props) => {
  const srfs = useSelector((state) => state.srfs.list);
  const dispatch = useDispatch();
  const [modifiedSRFs, setModifiedSRFs] = useState();
  const [isLoaded, setIsLoaded] = useState(true);
  const [viewSRFModal, setViewSRFModal] = useState(false);
  const [viewId, setViewId] = useState();
  const auth = useContext(AuthContext);
  const [error, setError] = useState();
  const filteredSRFs = useSelector((state) => state.filteredsrfs.list);
  useEffect(() => {
    if (srfs) {
      let addedzero = [];
      srfs.forEach((element) => {
        if (element.sno > 0 && element.sno < 10) {
          addedzero.push("0000" + element.sno);
        }
        if (element.sno > 9 && element.sno < 100) {
          addedzero.push("000" + element.sno);
        }
        if (element.sno > 99 && element.sno < 1000) {
          addedzero.push("00" + element.sno);
        }
        if (element.sno > 999 && element.sno < 10000) {
          addedzero.push("0" + element.sno);
        }
        if (element.sno > 9999 && element.sno < 100000) {
          addedzero.push("" + element.sno);
        }
      });

      const modifiedsrfs = srfs.map((v, i) => ({
        ...v,
        srfId:
          v.lab.symbol +
          "/" +
          v.year.toString().slice(2) +
          "/" +
          v.type +
          addedzero[i],
        sno: i + 1,
        company_name: v.Company.companyname,
        date: v.date.split("-").reverse().join("-"),
        agreed_date: v.agreed_date.split("-").reverse().join("-"),
        customer_dc_date: v.customer_dc_date.split("-").reverse().join("-"),
      }));
      setModifiedSRFs(modifiedsrfs);
      console.log(modifiedSRFs);
    }
  }, [srfs]);
  useEffect(() => {
    setIsLoaded(false);
    const requestOptions = {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + auth.token,
      },
      body: JSON.stringify({ labId: auth.labId }),
    };
    const errornotification = {
      title: "Error while Getting SRFs!!",
      description: "Getting List of SRFs Failed!!",
      icon: "error",
      state: true,
      timeout: 15000,
    };

    fetch(config.SERVER.URL + "/api/srf/getall", requestOptions)
      .then(async (response) => {
        const data = await response.json();

        if (data) {
          if (data.code === 200) {
            //console.log(data.data);
            setIsLoaded(true);
            dispatch(srfsActions.changesrfs(data.data));
          } else {
            setIsLoaded(true);
            errornotification.description = data.message;
            dispatch(notificationActions.changenotification(errornotification));
          }
        } else {
          setIsLoaded(true);
          dispatch(notificationActions.changenotification(errornotification));
        }
      })
      .catch((err) => {
        setIsLoaded(true);
        dispatch(notificationActions.changenotification(errornotification));
      });
  }, []);
  /*
  const srfdeleteHandler = async (v) => {
    setIsLoaded(false);
    const requestOptions = {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + auth.token,
      },
      body: JSON.stringify({ srfId: v }),
    };
    const errornotification = {
      title: "Error while Deleting SRF!!",
      description: "SRFId: " + v,
      icon: "error",
      state: true,
      timeout: 15000,
    };
    fetch(config.SERVER.URL + "/api/srf/deletesrf", requestOptions)
      .then(async (response) => {
        const data = await response.json();
        setIsLoaded(true);
        //console.log(data);
        if (data) {
          if (data.code === 200) {
            const newNotification = {
              title: "SRF Deleted Successfully",
              description: "SRFId: " + v,
              icon: "success",
              state: true,
              timeout: 15000,
            };
            //console.log(data);
            dispatch(srfsActions.changesrfs(data.data));
            dispatch(notificationActions.changenotification(newNotification));
          } else {
            dispatch(notificationActions.changenotification(errornotification));
          }
        } else {
          dispatch(notificationActions.changenotification(errornotification));
        }
      })
      .catch((err) => {
        dispatch(notificationActions.changenotification(errornotification));
      });
  };*/
  const srfViewHandler = (v) => {
    setViewSRFModal(true);
    setViewId(v);
  };

  const srfPreviewHandler = (v) => {
    //console.log(v);
    const requestOptions = {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + auth.token,
      },
      responseType: "blob",
      body: JSON.stringify({ labId: auth.labId, srfId: v }),
    };

    fetch(config.SERVER.URL + "/api/download/srf", requestOptions)
      .then(async (response) => {
        const srf = modifiedSRFs.filter((el) => {
          return el.id == v;
        });
        const fname = srf[0].srfId;
        const fnames = fname.split("/");

        const ffname = fnames[0] + "-" + fnames[1] + "-" + fnames[2] + ".xlsx";
        const reader = response.body.getReader();

        while (true) {
          const { value, done } = await reader.read();
          if (done) break;
          //console.log("Received", value);
          const url = window.URL.createObjectURL(new Blob([value]));
          //console.log(url);
          const link = document.createElement("a");
          link.href = url;
          link.setAttribute("download", ffname);
          document.body.appendChild(link);
          link.click();
        }
        //console.log("Response fully received");

        let data;
        /*const data = await response.json();
        setIsLoaded(true);
        console.log(response.data);*/
        if (data) {
          if (data.code === 200) {
            ////console.log(data);
          } else {
            setError(data.message);
            const newNotification = {
              title: "Getting SRF Preview Failed!!",
              description: data.message,
              icon: "error",
              state: true,
            };
            dispatch(notificationActions.changenotification(newNotification));
          }
        } else {
          setError("Error While Getting SRF Preview!!");
        }
      })
      .catch((err) => {
        setIsLoaded(true);
        setError("Error While Getting SRF Preview!!");
      });
  };

  const viewmodalHandler = () => {
    const srfviewmodal = viewSRFModal;
    setViewSRFModal(!srfviewmodal);
  };
  const ViewSRF = ({ value }) => (
    <Button
      variant="neutral"
      label="View"
      onClick={() => srfViewHandler(value)}
    />
  );

  const PreviewSRF = ({ value }) => (
    <Button
      variant="brand"
      label="Preview"
      onClick={() => srfPreviewHandler(value)}
    />
  );
  /*
  const DeleteSRF = ({ value }) => (
    <Button
      variant="destructive"
      label="Delete"
      onClick={() => srfdeleteHandler(value)}
    />
  );*/
  return (
    <div className="srfs_page">
      <div className="srfs__container">
        <div className="searchers__container">
          <div className="searchers">
            <CustomSearch
              options={modifiedSRFs}
              onfilter={(v) =>
                dispatch(filteredsrfsActions.changefilteredsrfs(v))
              }
              filterby="srfno"
              label="Search By SRF No."
            />
          </div>
          <div className="searchers">
            <CustomSearch
              options={modifiedSRFs}
              onfilter={(v) =>
                dispatch(filteredsrfsActions.changefilteredsrfs(v))
              }
              filterby="customer_dc"
              label="Search By Customer DC"
            />
          </div>
          <div className="searchers">
            <CustomSearch
              options={modifiedSRFs}
              onfilter={(v) =>
                dispatch(filteredsrfsActions.changefilteredsrfs(v))
              }
              filterby="companyname"
              label="Search By Company Name"
            />
          </div>
          <div className="searchers">
            <CustomSearch
              options={modifiedSRFs}
              onfilter={(v) =>
                dispatch(filteredsrfsActions.changefilteredsrfs(v))
              }
              filterby="customername"
              label="Search By Customer Name"
            />
          </div>
        </div>
        <TableWithBrowserPagination
          className="srfs__table"
          pageSize={5}
          data={filteredSRFs ? filteredSRFs : modifiedSRFs}
          keyField="sno"
          maxColumnWidth={300}
        >
          <Column header="S.No" field="sno" />
          <Column header="SRF No" field="srfId" />
          <Column header="SRF Date" field="date" />
          <Column header="Customer DC" field="customer_dc" />
          <Column header="Company Name" field="company_name" />
          <Column header="Agreed Date" field="agreed_date" />
          <Column header="Contact Person" field="contact_name" />
          <Column header="Contact Number" field="contact_number" />
          <Column header="Department" field="department" />
          <Column header="View SRF" field="id" component={ViewSRF} />
          {auth.department == "admin" || auth.department == "CSD" ? (
            <Column header="Preview" field="id" component={PreviewSRF} />
          ) : null}
        </TableWithBrowserPagination>
        {!isLoaded ? <Spinner size="medium" /> : null}
        {viewSRFModal ? (
          <ViewSRFModal
            isopen={viewSRFModal}
            onclose={viewmodalHandler}
            srfid={viewId}
          />
        ) : null}
      </div>
    </div>
  );
};

export default SRFsList;
